describe('Checkout Form - Card Expiry Validation', () => {
  beforeEach(() => {
    cy.visit('/checkout');
    cy.get('[data-testid="card-expiry-input"]').as('expiryInput');
    cy.get('[data-testid="card-expiry-error"]').as('expiryError');
    cy.get('[data-testid="checkout-form"]').as('checkoutForm');
  });

  it('should accept valid card expiry in MM/YY format', () => {
    cy.get('@expiryInput').clear().type('12/25');
    cy.get('@expiryInput').should('have.value', '12/25');
    cy.get('@expiryError').should('not.be.visible');
    cy.get('[data-testid="submit-button"]').click();
    cy.get('[data-testid="success-message"]').should('be.visible');
  });

  it('should reject invalid expiry format without slash', () => {
    cy.get('@expiryInput').clear().type('1225');
    cy.get('@expiryError').should('be.visible');
    cy.get('@expiryError').should('contain', 'Please enter expiry in MM/YY format');
    cy.get('[data-testid="submit-button"]').should('be.disabled');
  });

  it('should reject expired card dates', () => {
    const currentDate = new Date();
    const expiredMonth = String(currentDate.getMonth()).padStart(2, '0');
    const expiredYear = String(currentDate.getFullYear() - 1).slice(-2);

    cy.get('@expiryInput').clear().type(`${expiredMonth}/${expiredYear}`);
    cy.get('@expiryError').should('be.visible');
    cy.get('@expiryError').should('contain', 'Card has expired');
  });

  it('should auto-format input with slash separator', () => {
    cy.get('@expiryInput').clear().type('1225');
    cy.get('@expiryInput').should('have.value', '12/25');
  });

  it('should reject invalid month values', () => {
    cy.get('@expiryInput').clear().type('13/25');
    cy.get('@expiryError').should('be.visible');
    cy.get('@expiryError').should('contain', 'Invalid month');
  });

  it('should reject month value of 00', () => {
    cy.get('@expiryInput').clear().type('00/25');
    cy.get('@expiryError').should('be.visible');
    cy.get('@expiryError').should('contain', 'Invalid month');
  });

  it('should accept edge case of current month and year', () => {
    const currentDate = new Date();
    const currentMonth = String(currentDate.getMonth() + 1).padStart(2, '0');
    const currentYear = String(currentDate.getFullYear()).slice(-2);

    cy.get('@expiryInput').clear().type(`${currentMonth}/${currentYear}`);
    cy.get('@expiryError').should('not.be.visible');
  });

  it('should reject expiry with invalid characters', () => {
    cy.get('@expiryInput').clear().type('12@25');
    cy.get('@expiryError').should('be.visible');
    cy.get('@expiryError').should('contain', 'Please enter expiry in MM/YY format');
  });

  it('should clear error message when valid input is entered after invalid', () => {
    cy.get('@expiryInput').clear().type('99/25');
    cy.get('@expiryError').should('be.visible');
    cy.get('@expiryInput').clear().type('12/25');
    cy.get('@expiryError').should('not.be.visible');
  });

  it('should handle paste event with valid MM/YY format', () => {
    cy.get('@expiryInput').invoke('val', '12/25').trigger('change');
    cy.get('@expiryInput').should('have.value', '12/25');
    cy.get('@expiryError').should('not.be.visible');
  });

  it('should reject expiry with more than 5 characters', () => {
    cy.get('@expiryInput').clear().type('12/255');
    cy.get('@expiryInput').should('have.value', '12/25');
  });
});
